INSERT INTO `tb_project_chat_messages` (`message_id`, `project_id`, `user_id`, `message_text`, `reply_to_message_id`, `message_created_at`) VALUES
('PCM202605040000001', 'PRO202604280000001', 'USE202604010000006', 'เริ่มโปรเจกต์ระบบจองทัวร์วันนี้ครับ kickoff 10 โมงที่ห้องประชุมเล็ก', NULL, '2026-05-04 09:20:00.068'),
('PCM202605040000002', 'PRO202604280000001', 'USE202604010000009', 'แนบภาพร่างหน้าจอจองทัวร์จากที่คุยกันเมื่อเช้าค่ะ', NULL, '2026-05-04 11:05:00.282'),
('PCM202605040000003', 'PRO202604280000001', 'USE202604010000008', 'ปฏิทินที่นั่งว่างทำเป็นรายเดือนได้ไหมคะ ลูกค้าอยากเห็นทั้งเดือน', 'PCM202605040000002', '2026-05-04 11:20:00.207'),
('PCM202605040000004', 'PRO202604280000001', 'USE202604010000006', 'ได้ครับ จอคอมแสดงรายเดือน มือถือแสดงรายสัปดาห์', 'PCM202605040000003', '2026-05-04 13:10:00.064'),
('PCM202605040000005', 'PRO202605040000001', 'USE202604010000006', 'โปรเจกต์ภายใน: ระบบบริหารงานของเราเอง ลงงานในบอร์ดนี้นะครับ', NULL, '2026-05-04 13:30:00.062'),
('PCM202605130000001', 'PRO202605120000001', 'USE202604010000006', 'โปรเจกต์เว็บไซต์คลินิกเริ่มวันนี้ ปิงดูแลระบบนัดหมาย มิ้นท์ทำหน้าเว็บครับ', NULL, '2026-05-13 09:30:00.061'),
('PCM202605200000001', 'PRO202605120000001', 'USE202604010000009', 'แบบหน้าแรกเวอร์ชันแรกค่ะ คุณหมอชอบโทนสีฟ้าอ่อน', NULL, '2026-05-20 15:20:00.211'),
('PCM202606010000001', 'PRO202605280000001', 'USE202604010000006', 'เริ่มระบบจองห้องพักอันดามันครับ งวดแรกเน้นหน้าจอจองและปฏิทินห้องว่าง', NULL, '2026-06-01 09:15:00.192'),
('PCM202606120000001', 'PRO202604280000001', 'USE202604010000003', 'ลูกค้าขอเพิ่มช่องหมายเหตุตอนจอง (แพ้อาหาร/ที่นั่งเด็ก) รบกวนประเมินเวลาด้วยครับ', NULL, '2026-06-12 10:40:00.065'),
('PCM202606120000002', 'PRO202604280000001', 'USE202604010000006', 'เพิ่มได้ครับ ใช้เวลาครึ่งวัน ไม่กระทบกำหนดส่งงวด 2', 'PCM202606120000001', '2026-06-12 11:15:00.064'),
('PCM202606180000001', 'PRO202605280000001', 'USE202604010000009', 'หน้าจอปฏิทินห้องว่างตามฤดูกาลค่ะ ช่วยดูว่าปุ่มเปลี่ยนเดือนใหญ่พอบนมือถือไหม', NULL, '2026-06-18 14:30:00.075'),
('PCM202606180000002', 'PRO202605280000001', 'USE202604010000012', 'บนมือถือกดง่ายครับ ขอให้วันที่จองเต็มเป็นสีเทาชัดกว่านี้นิดนึง', 'PCM202606180000001', '2026-06-18 15:05:00.063'),
('PCM202607100000001', 'PRO202605120000001', 'USE202604010000007', 'เปิดใช้งานจริงแล้วครับ ระบบแจ้งเตือนนัดผ่าน LINE ทำงานปกติ', NULL, '2026-07-10 17:40:00.062'),
('PCM202607150000001', 'PRO202605280000001', 'USE202604010000003', 'ลูกค้ารีสอร์ทขอให้ราคาวันหยุดยาวตั้งล่วงหน้าได้ทั้งปีครับ', NULL, '2026-07-15 10:20:00.060'),
('PCM202607150000002', 'PRO202605280000001', 'USE202604010000007', 'รองรับแล้วครับ ตั้งช่วงราคาได้ไม่จำกัด', 'PCM202607150000001', '2026-07-15 11:00:00.071'),
('PCM202607210000001', 'PRO202607200000001', 'USE202604010000006', 'เริ่มระบบรับซื้อปาล์มครับ ทีมหน้างานไปโรงงานทุกวันพฤหัส', NULL, '2026-07-21 09:30:00.074'),
('PCM202607290000001', 'PRO202604280000001', 'USE202604010000010', 'ทดสอบชำระเงินผ่าน QR ครบทุกธนาคารแล้ว ผ่านทั้งหมดครับ', NULL, '2026-07-29 16:05:00.087'),
('PCM202608030000001', 'PRO202604280000001', 'USE202604010000006', 'ปิดโปรเจกต์เรียบร้อย ลูกค้าตรวจรับแล้ว ขอบคุณทุกคนครับ ต่อจากนี้เป็นสัญญาดูแลรายเดือน', NULL, '2026-08-03 09:10:00.062'),
('PCM202608060000001', 'PRO202607200000001', 'USE202604010000008', 'รูปจุดรับซื้อที่ 1 ค่ะ ตาชั่งต่อสาย RS-232 ได้ตามที่คุยไว้', NULL, '2026-08-06 15:40:00.070'),
('PCM202608250000001', 'PRO202608240000001', 'USE202604010000006', 'Kickoff แอปจองดำน้ำครับ ลูกค้าสิงคโปร์ เอกสารทั้งหมดเป็นภาษาอังกฤษนะครับ', NULL, '2026-08-25 10:00:00.087'),
('PCM202608280000001', 'PRO202607200000001', 'USE202604010000011', 'ส่งต่องานโมดูลรับซื้อให้ฝนแล้วครับ เอกสารอยู่ในโฟลเดอร์ส่งมอบ ขอบคุณทุกคนครับ', NULL, '2026-08-28 17:10:00.059'),
('PCM202608280000002', 'PRO202607200000001', 'USE202604010000006', 'ขอบคุณเอกมากครับ โชคดีกับการเรียนต่อ', 'PCM202608280000001', '2026-08-28 17:25:00.064'),
('PCM202609100000001', 'PRO202605280000001', 'USE202604010000012', 'แผนย้ายข้อมูลห้องพักจากระบบเดิม: เสาร์ที่ 12 ก.ย. 09:00-13:00 ระหว่างที่รีสอร์ทปิดรับจองชั่วคราว', NULL, '2026-09-10 16:30:00.058'),
('PCM202609120000001', 'PRO202605280000001', 'USE202604010000012', 'ย้ายข้อมูลเสร็จแล้วครับ ห้อง 86 ห้อง การจองล่วงหน้า 412 รายการ ตรงกับระบบเดิมทุกรายการ', NULL, '2026-09-12 13:20:00.107'),
('PCM202609180000001', 'PRO202608240000001', 'USE202604010000009', 'ลูกค้าอนุมัติดีไซน์ทั้ง 12 หน้าจอแล้วค่ะ', NULL, '2026-09-18 16:15:00.073'),
('PCM202610010000001', 'PRO202605280000001', 'USE202604010000006', 'ระบบขึ้นใช้งานจริงเมื่อคืน เช็กอินแรกของวันเรียบร้อยครับ ขอบคุณทุกคนที่อยู่ดึก', NULL, '2026-10-01 08:45:00.060'),
('PCM202610130000001', 'PRO202607200000001', 'USE202604010000010', 'วันแรกเปิดใช้จริงที่โรงงาน รับซื้อได้ทั้ง 3 จุด ไม่มีข้อผิดพลาดครับ', NULL, '2026-10-13 15:20:00.070'),
('PCM202610140000001', 'PRO202607200000001', 'USE202604010000008', 'ยอดรับซื้อวันแรก 312 ตันค่ะ กราฟแนบ', NULL, '2026-10-14 09:05:00.090'),
('PCM202610200000001', 'PRO202608240000001', 'USE202604010000007', 'ระบบจองฝั่ง API เสร็จ 80% สัปดาห์หน้าส่ง TestFlight ให้ลูกค้าลองครับ', NULL, '2026-10-20 11:30:00.058'),
('PCM202610200000002', 'PRO202605040000001', 'USE202604010000012', 'ระบบลงเวลาเข้า-ออกงานใช้จริงมาเกือบ 5 เดือน มีคนขอให้แสดงแผนที่ตอนกด ใส่ไว้ในงานถัดไปครับ', NULL, '2026-10-20 10:10:00.058');
