INSERT INTO `tb_task_chat_messages` (`message_id`, `task_id`, `user_id`, `message_text`, `reply_to_message_id`, `message_created_at`) VALUES
('MES202605180000001', 'TAS202604280000004', 'USE202604010000008', 'API ราคาทัวร์ส่งราคาเด็กมาเป็นราคาเต็ม ต้องคิดส่วนลดฝั่งเราไหมคะ', NULL, '2026-05-18 10:30:00.364'),
('MES202605180000002', 'TAS202604280000004', 'USE202604010000011', 'ใช่ครับ ราคาเด็ก 70% ของผู้ใหญ่ ผมเพิ่มในหลังบ้านให้ตั้งได้แล้ว', NULL, '2026-05-18 10:45:00.229'),
('MES202607020000001', 'TAS202605280000004', 'USE202604010000007', 'โครงสร้างตารางห้องพักแยกห้องกับประเภทห้องแล้วนะครับ', NULL, '2026-07-02 14:00:00.095'),
('MES202607020000002', 'TAS202605280000004', 'USE202604010000012', 'รับทราบครับ ระบบแม่บ้านจะอิงสถานะห้องรายห้อง', NULL, '2026-07-02 14:20:00.098'),
('MES202608130000001', 'TAS202607200000004', 'USE202604010000010', 'ทดสอบชั่งน้ำหนักรถพ่วงแล้ว ค่ากลับมาช้า 3-4 วินาที รับได้ไหมครับ', NULL, '2026-08-13 11:10:00.095'),
('MES202608130000002', 'TAS202607200000004', 'USE202604010000008', 'รับได้ค่ะ ตาชั่งรุ่นนี้ส่งค่าทุก 3 วินาทีอยู่แล้ว', NULL, '2026-08-13 11:30:00.095'),
('MES202609300000001', 'TAS202605280000004', 'USE202604010000006', 'ติดตั้งเสร็จ ตรวจ SSL และสำรองข้อมูลอัตโนมัติแล้ว หน้าจอหลังติดตั้งแนบไว้', NULL, '2026-09-30 21:10:00.116');
